"""Demo: a chordal graph is perfect (chi = omega), attained by greedy colouring."""
from itertools import combinations
from typing import Dict, List, Set, Tuple

Graph = Tuple[int, List[Set[int]]]

def make_graph(n: int, edges: List[Tuple[int, int]]) -> Graph:
    adj: List[Set[int]] = [set() for _ in range(n)]
    for u, v in edges:
        if u != v:
            adj[u].add(v); adj[v].add(u)
    return n, adj

def earlier_neighbours(g: Graph, v: int) -> Set[int]:
    _, adj = g
    return {w for w in adj[v] if w < v}

def clique_number(g: Graph) -> int:
    n, adj = g
    for size in range(n, 0, -1):
        for s in combinations(range(n), size):
            if all(b in adj[a] for a, b in combinations(s, 2)):
                return size
    return 0

def greedy_peo_colouring(g: Graph) -> Dict[int, int]:
    n, _ = g
    colour: Dict[int, int] = {}
    for v in range(n):
        forbidden = {colour[w] for w in earlier_neighbours(g, v)}
        c = 0
        while c in forbidden:
            c += 1
        colour[v] = c
    return colour

if __name__ == "__main__":
    g = make_graph(4, [(0, 1), (1, 2), (2, 3), (3, 0), (0, 2)])  # 4-cycle + chord
    col = greedy_peo_colouring(g)
    print("omega =", clique_number(g), " colours used =", max(col.values()) + 1)
    print("colouring:", col)

"""Demo: interval graphs -> linear-scan register allocation (registers = peak overlap)."""
from typing import Dict, List, Set, Tuple

def interval_graph(intervals: List[Tuple[int, int]]) -> Tuple[int, List[Set[int]]]:
    order = sorted(range(len(intervals)), key=lambda i: intervals[i][0])
    iv = [intervals[i] for i in order]
    n = len(iv)
    adj: List[Set[int]] = [set() for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if iv[i][0] <= iv[j][1] and iv[j][0] <= iv[i][1]:
                adj[i].add(j); adj[j].add(i)
    return n, adj

def max_overlap(intervals: List[Tuple[int, int]]) -> int:
    events = []
    for lo, hi in intervals:
        events += [(lo, 1), (hi + 1, -1)]
    events.sort()
    cur = best = 0
    for _, d in events:
        cur += d; best = max(best, cur)
    return best

def allocate(intervals: List[Tuple[int, int]]) -> Dict[int, int]:
    n, adj = interval_graph(intervals)
    reg: Dict[int, int] = {}
    for v in range(n):
        used = {reg[w] for w in adj[v] if w < v}
        r = 0
        while r in used:
            r += 1
        reg[v] = r
    return reg

if __name__ == "__main__":
    iv = [(0, 4), (1, 2), (3, 6), (5, 8), (2, 7), (6, 9)]
    reg = allocate(iv)
    print("peak overlap (omega) =", max_overlap(iv))
    print("registers used =", max(reg.values()) + 1)
    print("assignment:", reg)

"""Demo: the odd cycle C5 is NOT chordal and chi (=3) exceeds omega (=2)."""
from itertools import combinations
from typing import List, Set, Tuple

def make_graph(n: int, edges: List[Tuple[int, int]]):
    adj: List[Set[int]] = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v); adj[v].add(u)
    return n, adj

def clique_number(g):
    n, adj = g
    for size in range(n, 0, -1):
        for s in combinations(range(n), size):
            if all(b in adj[a] for a, b in combinations(s, 2)):
                return size
    return 0

def chi(g):
    n, adj = g
    def kcol(k):
        col = [-1] * n
        def bt(v):
            if v == n:
                return True
            for c in range(k):
                if all(col[w] != c for w in adj[v] if col[w] != -1):
                    col[v] = c
                    if bt(v + 1):
                        return True
                    col[v] = -1
            return False
        return bt(0)
    k = 1
    while not kcol(k):
        k += 1
    return k

if __name__ == "__main__":
    g = make_graph(5, [(0, 1), (1, 2), (2, 3), (3, 4), (4, 0)])
    print("C5: omega =", clique_number(g), " chi =", chi(g))
    print("Since 3 > 2, non-chordal graphs need not be perfect.")

