from typing import Dict, List, Set, Tuple

Graph = Tuple[int, List[Set[int]]]

def greedy_peo_colouring(g: Graph) -> Dict[int, int]:
    """Optimal colouring of a graph whose natural order 0..n-1 is a perfect
    elimination ordering. Colour each vertex with the least colour avoided by its
    earlier (already-coloured) neighbours. Uses exactly omega(G) colours."""
    n, adj = g
    colour: Dict[int, int] = {}
    for v in range(n):
        forbidden: Set[int] = {colour[w] for w in adj[v] if w < v}
        c = 0
        while c in forbidden:
            c += 1
        colour[v] = c
    return colour

from typing import List, Set, Tuple

Graph = Tuple[int, List[Set[int]]]

def maximum_cardinality_search(g: Graph) -> List[int]:
    """Maximum Cardinality Search. Numbers vertices from n down to 1, each time
    choosing an unnumbered vertex adjacent to the most already-numbered vertices.
    Returns the elimination order (index 0 = first to eliminate). Its reverse is a
    perfect elimination ordering iff the graph is chordal."""
    n, adj = g
    weight: List[int] = [0] * n
    numbered: List[bool] = [False] * n
    order: List[int] = []
    for _ in range(n):
        best = -1
        best_w = -1
        for v in range(n):
            if not numbered[v] and weight[v] > best_w:
                best_w, best = weight[v], v
        numbered[best] = True
        order.append(best)
        for w in adj[best]:
            if not numbered[w]:
                weight[w] += 1
    return list(reversed(order))

